function withdrawIBT(
    uint256 ibts,
    address receiver,
    address owner
) public override returns (uint256 shares) { // @audit this is `public` but should just be `internal`
    _beforeWithdraw(IERC4626(ibt).previewRedeem(ibts), owner);
